INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2031QKC', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 3, 'mcq', E'If $f(x) = 2^x$ and $g(x) = x^2 - 3x$, what is the value of $f(g(2))$?', NULL, $lyceon_json$[{"key":"A","text":"$-4$"},{"key":"B","text":"$-2$"},{"key":"C","text":"$\\frac{1}{4}$"},{"key":"D","text":"$4$"}]$lyceon_json$::jsonb, 'C', NULL, E'First evaluate $g(2) = (2)^2 - 3(2) = 4 - 6 = -2$. Then $f(g(2)) = f(-2) = 2^{-2} = \\frac{1}{2^2} = \\frac{1}{4}$. The distractor $-4$ results from incorrectly interpreting $2^{-2}$ as $-(2^2) = -4$, confusing a negative exponent with negation. The distractor $-2$ results from stopping at $g(2) = -2$ without applying $f$. The distractor $4$ results from ignoring the negative sign in the exponent and computing $2^2 = 4$ instead of $2^{-2}$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"misread_question"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM204CPZI', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 1, 'mcq', E'A random sample of $200$ residents in a town found that $118$ supported building a new park. The margin of error for this estimate is $\\pm 6\\%$. Which of the following is the most likely range of the percentage of all residents who support the new park?', NULL, $lyceon_json$[{"key":"A","text":"$47\\%$ to $59\\%$"},{"key":"B","text":"$53\\%$ to $65\\%$"},{"key":"C","text":"$56\\%$ to $62\\%$"},{"key":"D","text":"$59\\%$ to $65\\%$"}]$lyceon_json$::jsonb, 'B', NULL, E'The sample proportion is $\\frac{118}{200} = 59\\%$. Applying the margin of error of $\\pm 6\\%$ gives the interval $59\\% - 6\\% = 53\\%$ to $59\\% + 6\\% = 65\\%$. The distractor $47\\%$ to $59\\%$ subtracts the margin from both the lower and upper ends instead of centering the interval on $59\\%$. The distractor $56\\%$ to $62\\%$ uses half the margin of error ($\\pm 3\\%$) instead of the full $\\pm 6\\%$. The distractor $59\\%$ to $65\\%$ only adds the margin and omits the lower bound, treating it as one-sided.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM208TGZW', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 3, 'grid_in', E'A car uses fuel at a rate of $7$ gallons per $203$ miles. The fuel tank holds $17$ gallons. If the car has already traveled $145$ miles on a full tank, how many more miles can the car travel before the tank is empty?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '348', ARRAY['348'], E'The car''s fuel efficiency is $\\frac{203}{7} = 29$ miles per gallon. The fuel consumed for $145$ miles is $\\frac{145}{29} = 5$ gallons. The remaining fuel is $17 - 5 = 12$ gallons. The car can travel $12 \\times 29 = 348$ more miles. A common error is computing $17 \\times 29 = 493$ total range and forgetting to subtract the $145$ miles already traveled, giving $493 - 145 = 348$ — which happens to match because both approaches are algebraically equivalent. Another error is miscalculating the fuel used (e.g., using $\\frac{145}{203} \\times 17$ instead of $\\frac{145}{29}$), which would yield an incorrect remaining distance.', NULL, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM248VA7Q', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 2, 'mcq', E'The function $g(t) = 250 - 13t$ models the amount of water, in gallons, remaining in a tank $t$ hours after a valve is opened. What does the number $13$ represent in this function?', NULL, $lyceon_json$[{"key":"A","text":"The initial amount of water in the tank, in gallons"},{"key":"B","text":"The amount of water remaining after $13$ hours"},{"key":"C","text":"The rate at which water drains from the tank, in gallons per hour"},{"key":"D","text":"The number of hours until the tank is empty"}]$lyceon_json$::jsonb, 'C', NULL, E'In the linear function $g(t) = 250 - 13t$, the coefficient of $t$ represents the rate of change. Since $g$ decreases by $13$ for every increase of $1$ in $t$, the number $13$ is the rate at which water drains from the tank, in gallons per hour. The initial amount of water is $250$ gallons (the constant term when $t = 0$), not $13$. The amount remaining after $13$ hours would be $g(13) = 250 - 169 = 81$, which is a computed output, not what the number $13$ represents in the equation. The number of hours until the tank is empty would be found by solving $250 - 13t = 0$, giving $t \\approx 19.2$ hours, not $13$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"misread_question"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM268YQJP', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 2, 'mcq', E'A right circular cylinder has a radius of $3$ feet and a height of $7$ feet. What is the volume, in cubic feet, of the cylinder?', NULL, $lyceon_json$[{"key":"A","text":"$21\\pi$"},{"key":"B","text":"$42\\pi$"},{"key":"C","text":"$63\\pi$"},{"key":"D","text":"$147\\pi$"}]$lyceon_json$::jsonb, 'C', NULL, E'The volume of a cylinder is $V = \\pi r^2 h$. Substituting $r = 3$ and $h = 7$: $V = \\pi(3)^2(7) = \\pi(9)(7) = 63\\pi$ cubic feet. The value $21\\pi$ results from using $\\pi r h = \\pi(3)(7)$ instead of $\\pi r^2 h$, omitting the squaring of the radius. The value $42\\pi$ comes from using the lateral surface area formula $2\\pi r h = 2\\pi(3)(7)$ instead of the volume formula. The value $147\\pi$ comes from using $\\pi r h^2 = \\pi(3)(49)$, which swaps the roles of the radius and height in the squaring step.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
