INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM277MP2W', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 3, 'mcq', E'A surveyor at point $P$ measures the angle of elevation to the top of a tower as $\\theta$, where $\\tan(\\theta) = \\frac{5}{8}$. The surveyor walks $15$ meters directly toward the tower to point $R$ and measures the new angle of elevation as $\\phi$, where $\\tan(\\phi) = \\frac{5}{3}$. What is the height of the tower, in meters?', NULL, $lyceon_json$[{"key":"A","text":"$9$"},{"key":"B","text":"$12$"},{"key":"C","text":"$15$"},{"key":"D","text":"$24$"}]$lyceon_json$::jsonb, 'C', NULL, E'Let $h$ be the height of the tower and $d$ the initial horizontal distance from point $P$ to the base. From point $P$: $\\tan(\\theta) = \\frac{h}{d} = \\frac{5}{8}$, so $h = \\frac{5d}{8}$. From point $R$, which is $15$ meters closer: $\\tan(\\phi) = \\frac{h}{d - 15} = \\frac{5}{3}$, so $h = \\frac{5(d - 15)}{3}$. Setting these equal: $\\frac{5d}{8} = \\frac{5(d - 15)}{3}$. Dividing both sides by $5$: $\\frac{d}{8} = \\frac{d - 15}{3}$. Cross-multiplying: $3d = 8(d - 15) = 8d - 120$, so $5d = 120$ and $d = 24$. Therefore $h = \\frac{5(24)}{8} = 15$ meters. The value $9$ is the remaining distance $d - 15 = 24 - 15 = 9$, an intermediate quantity, not the height. The value $12$ results from a computational error such as $\\frac{5 \\times 24}{10}$. The value $24$ is the initial distance $d$, not the tower height.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM27UBQMH', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 3, 'mcq', E'The equation of a circle is $(x + 1)^2 + (y - 3)^2 = 25$. The line $y = 2x$ intersects the circle at two points. What is the distance between these two points of intersection?', NULL, $lyceon_json$[{"key":"A","text":"$4$"},{"key":"B","text":"$4\\sqrt{5}$"},{"key":"C","text":"$8$"},{"key":"D","text":"$10$"}]$lyceon_json$::jsonb, 'B', NULL, E'Substituting $y = 2x$ into the circle equation: $(x + 1)^2 + (2x - 3)^2 = 25$. Expanding: $x^2 + 2x + 1 + 4x^2 - 12x + 9 = 25$, which simplifies to $5x^2 - 10x + 10 = 25$, or $5x^2 - 10x - 15 = 0$. Dividing by $5$: $x^2 - 2x - 3 = 0$, which factors as $(x - 3)(x + 1) = 0$, giving $x = 3$ or $x = -1$. The corresponding points are $(3, 6)$ and $(-1, -2)$. The distance between them is $\\sqrt{(3 - (-1))^2 + (6 - (-2))^2} = \\sqrt{16 + 64} = \\sqrt{80} = 4\\sqrt{5}$. The value $4$ accounts only for the horizontal separation $|3 - (-1)|$. The value $8$ accounts only for the vertical separation $|6 - (-2)|$. The value $10$ equals the diameter $2r = 2(5)$, but the chord formed by the line is not a diameter since the line does not pass through the center $(-1, 3)$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM27X7TUX', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 2, 'mcq', E'A hospital study tracked $1{,}200$ patients over $5$ years and found that those who ate more than $4$ servings of vegetables per day had $31\\%$ lower rates of heart disease than those who ate fewer than $2$ servings per day. A news article concluded that eating vegetables prevents heart disease. Which of the following is the most valid criticism of the article''s conclusion?', NULL, $lyceon_json$[{"key":"A","text":"The study did not include enough patients to draw any conclusion."},{"key":"B","text":"Because the study was observational, it can establish an association but not a cause-and-effect relationship, so other factors may explain the result."},{"key":"C","text":"The study should have measured fruit consumption as well before drawing conclusions."},{"key":"D","text":"The conclusion is valid because the study was conducted at a hospital with reliable records."}]$lyceon_json$::jsonb, 'B', NULL, E'The study tracked patients without randomly assigning them to dietary groups, making it observational. Observational studies can identify associations but cannot establish causation because confounding variables (such as exercise habits, socioeconomic status, or other dietary factors) may explain the observed relationship. The criticism that the sample size was insufficient is unfounded, since $1{,}200$ patients over $5$ years is a substantial dataset. The suggestion to measure fruit consumption addresses a different research question and does not address the core issue of causation versus association. The claim that hospital records validate a causal conclusion conflates data quality with study design limitations.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM28VCVGI', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 1, 'grid_in', E'A line of best fit for a scatterplot is given by $y = 3x + 11$. According to this model, what is the predicted value of $y$ when $x = 9$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '38', ARRAY['38'], E'Substituting $x = 9$ into the equation gives $y = 3(9) + 11 = 27 + 11 = 38$.', NULL, NULL, 'draft', 1, 30, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM28WNNJM', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 2, 'mcq', E'A machine fills $84$ bottles in $7$ minutes. A second machine fills bottles at $\\frac{3}{4}$ the rate of the first machine. How many bottles does the second machine fill in $12$ minutes?', NULL, $lyceon_json$[{"key":"A","text":"$63$"},{"key":"B","text":"$108$"},{"key":"C","text":"$126$"},{"key":"D","text":"$144$"}]$lyceon_json$::jsonb, 'B', NULL, E'The first machine fills $\\frac{84}{7} = 12$ bottles per minute. The second machine fills $\\frac{3}{4} \\times 12 = 9$ bottles per minute. In $12$ minutes, the second machine fills $9 \\times 12 = 108$ bottles. The distractor $63$ results from computing $\\frac{3}{4} \\times 84 = 63$ without adjusting for the different time period. The distractor $126$ results from a multiplication error such as $9 \\times 14$ instead of $9 \\times 12$. The distractor $144$ results from computing $12 \\times 12 = 144$, ignoring the $\\frac{3}{4}$ rate factor entirely.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM29T336Z', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 1, 'grid_in', E'A triangle has a base of $17$ centimeters and a height of $6$ centimeters. What is the area, in square centimeters, of the triangle?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '51', ARRAY['51'], E'The area of a triangle is $A = \\frac{1}{2} \\times \\text{base} \\times \\text{height}$. Substituting: $A = \\frac{1}{2} \\times 17 \\times 6 = \\frac{102}{2} = 51$ square centimeters. A common error is to forget the factor of $\\frac{1}{2}$ and compute $17 \\times 6 = 102$, which gives the area of a parallelogram with the same base and height rather than a triangle.', NULL, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2A4SDR4', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 2, 'mcq', E'In a group of $40$ students, $17$ play a sport and $23$ do not. Of those who play a sport, $11$ also participate in a club. Of those who do not play a sport, $9$ participate in a club. If a student is selected at random from those who participate in a club, what is the probability that the student plays a sport?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{11}{17}$"},{"key":"B","text":"$\\frac{11}{40}$"},{"key":"C","text":"$\\frac{11}{20}$"},{"key":"D","text":"$\\frac{9}{20}$"}]$lyceon_json$::jsonb, 'C', NULL, E'The total number of students who participate in a club is $11 + 9 = 20$. Among these $20$ club participants, $11$ play a sport. Therefore the conditional probability is $\\frac{11}{20}$. The distractor $\\frac{11}{17}$ computes the probability of being in a club given that a student plays a sport, reversing the condition. The distractor $\\frac{11}{40}$ divides by the total number of students rather than restricting to club participants. The distractor $\\frac{9}{20}$ uses the number of non-sport club members in the numerator instead of sport-playing club members.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2ACBN4L', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 1, 'mcq', E'A circle has center $(-4, 7)$ and radius $3$. Which of the following is the equation of the circle?', NULL, $lyceon_json$[{"key":"A","text":"$(x + 4)^2 + (y - 7)^2 = 9$"},{"key":"B","text":"$(x - 4)^2 + (y + 7)^2 = 9$"},{"key":"C","text":"$(x + 4)^2 + (y - 7)^2 = 3$"},{"key":"D","text":"$(x - 4)^2 + (y - 7)^2 = 9$"}]$lyceon_json$::jsonb, 'A', NULL, E'The standard form of a circle with center $(h, k)$ and radius $r$ is $(x - h)^2 + (y - k)^2 = r^2$. Substituting $h = -4$, $k = 7$, and $r = 3$: $(x - (-4))^2 + (y - 7)^2 = 3^2$, which simplifies to $(x + 4)^2 + (y - 7)^2 = 9$. The equation $(x - 4)^2 + (y + 7)^2 = 9$ reverses both signs, placing the center at $(4, -7)$. The equation $(x + 4)^2 + (y - 7)^2 = 3$ uses the radius instead of the radius squared on the right side. The equation $(x - 4)^2 + (y - 7)^2 = 9$ only handles the $y$-coordinate correctly while using the wrong sign for $x$, placing the center at $(4, 7)$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2AFIB1X', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 2, 'mcq', E'The line of best fit for a data set is $y = -4x + 53$. One of the data points is $(7, 29)$. What is the residual for this data point?', NULL, $lyceon_json$[{"key":"A","text":"$-4$"},{"key":"B","text":"$4$"},{"key":"C","text":"$25$"},{"key":"D","text":"$29$"}]$lyceon_json$::jsonb, 'B', NULL, E'The predicted value at $x = 7$ is $y = -4(7) + 53 = -28 + 53 = 25$. The residual is the actual value minus the predicted value: $29 - 25 = 4$. The distractor $-4$ results from computing predicted minus actual ($25 - 29$), reversing the residual formula. The distractor $25$ is the predicted value itself, not the residual. The distractor $29$ is the actual $y$-value of the data point, not the residual.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2BT7H2B', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 3, 'grid_in', E'In triangle $DEF$, the measure of angle $D$ is three times the measure of angle $E$, and the measure of angle $F$ is $6°$ more than twice the measure of angle $E$. What is the measure, in degrees, of angle $D$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '87', ARRAY['87'], E'Let the measure of angle $E$ be $x$ degrees. Then angle $D = 3x$ and angle $F = 2x + 6$. Since the angles of a triangle sum to $180°$, we have $x + 3x + (2x + 6) = 180$. Simplifying gives $6x + 6 = 180$, so $6x = 174$ and $x = 29$. Therefore angle $D = 3(29) = 87°$. A common error is to stop at $x = 29$ and report the measure of angle $E$ instead of angle $D$. Another error is to forget the constant $6$ when combining terms, which would yield $6x = 180$ and $x = 30$, giving $3(30) = 90°$ for angle $D$.', NULL, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2C37BCC', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 3, 'mcq', E'Which expression is equivalent to $$\\frac{x^2 - 9}{x^2 + 7x + 12} \\cdot \\frac{x^2 + 8x + 16}{x^2 - x - 6}$$ for all values of $x$ where it is defined?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{x + 3}{x + 2}$"},{"key":"B","text":"$\\frac{x + 2}{x + 4}$"},{"key":"C","text":"$1$"},{"key":"D","text":"$\\frac{x + 4}{x + 2}$"}]$lyceon_json$::jsonb, 'D', NULL, E'Factor each polynomial: $x^2 - 9 = (x + 3)(x - 3)$, $x^2 + 7x + 12 = (x + 3)(x + 4)$, $x^2 + 8x + 16 = (x + 4)^2$, and $x^2 - x - 6 = (x - 3)(x + 2)$. The product becomes $$\\frac{(x+3)(x-3)}{(x+3)(x+4)} \\cdot \\frac{(x+4)^2}{(x-3)(x+2)}.$$ Cancelling the common factors $(x+3)$, $(x-3)$, and one $(x+4)$ yields $\\frac{x+4}{x+2}$. The distractor $\\frac{x+3}{x+2}$ results from incorrectly cancelling factors and retaining $(x+3)$ in the numerator instead of $(x+4)$. The distractor $\\frac{x+2}{x+4}$ results from inverting the simplified fraction. The distractor $1$ results from incorrectly assuming all factors cancel completely.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
