INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2DL4CMR', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 1, 'grid_in', E'What is the $y$-intercept of the line $5x + 3y = 27$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '9', ARRAY['9'], E'The $y$-intercept occurs when $x = 0$. Substituting $x = 0$ into the equation gives $3y = 27$, so $y = 9$.', NULL, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2DZ89ZS', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 2, 'grid_in', E'In a $30°$-$60°$-$90°$ triangle, the side opposite the $60°$ angle has length $9\\sqrt{3}$. What is the length of the hypotenuse?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '18', ARRAY['18'], E'In a $30°$-$60°$-$90°$ triangle, the sides are in the ratio $x : x\\sqrt{3} : 2x$, where $x$ is the length of the side opposite the $30°$ angle, $x\\sqrt{3}$ is opposite the $60°$ angle, and $2x$ is the hypotenuse. Setting $x\\sqrt{3} = 9\\sqrt{3}$ gives $x = 9$. The hypotenuse is $2x = 2(9) = 18$. A common error is to multiply $9\\sqrt{3}$ by $2$ to get $18\\sqrt{3}$, which confuses the side opposite $60°$ with the shortest side. Another error is to divide $9\\sqrt{3}$ by $\\sqrt{3}$ correctly to get $9$ but then report that value instead of doubling it for the hypotenuse.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2ED3LLA', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 2, 'grid_in', E'In a school survey of $230$ students, $92$ students selected basketball as their favorite sport. What percent of the surveyed students selected basketball?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '40', ARRAY['40'], E'The percent is $\\frac{92}{230} \\times 100 = 0.4 \\times 100 = 40\\%$. A common error is inverting the fraction and computing $\\frac{230}{92} \\approx 2.5$, which does not represent a valid percentage of the whole. Another error is computing $\\frac{92}{230}$ and reporting $0.4$ instead of $40$.', NULL, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2EFN4GL', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 3, 'mcq', E'The price of a stock increased by $40\\%$ on Monday and then decreased by $25\\%$ on Tuesday. What was the overall percent change in the stock price from the beginning of Monday to the end of Tuesday?', NULL, $lyceon_json$[{"key":"A","text":"$5\\%$ increase"},{"key":"B","text":"$10\\%$ increase"},{"key":"C","text":"$15\\%$ increase"},{"key":"D","text":"$65\\%$ increase"}]$lyceon_json$::jsonb, 'A', NULL, E'Let the original price be $P$. After Monday''s $40\\%$ increase, the price is $1.40P$. After Tuesday''s $25\\%$ decrease, the price is $1.40P \\times 0.75 = 1.05P$. The overall change is $1.05P - P = 0.05P$, which is a $5\\%$ increase. The distractor $10\\%$ results from computing $40\\% \\times 25\\% = 10\\%$ as if the percentages multiply directly. The distractor $15\\%$ results from subtracting $25\\%$ from $40\\%$, treating sequential percentage changes as additive. The distractor $65\\%$ results from adding $40\\%$ and $25\\%$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2FYA9K3', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 1, 'grid_in', E'If $x^2 = 289$, what is the positive value of $x$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '17', ARRAY['17'], E'Taking the square root of both sides of $x^2 = 289$ gives $x = \\pm\\sqrt{289}$. Since $17^2 = 289$, the solutions are $x = 17$ and $x = -17$. The question asks for the positive value, so the answer is $17$.', NULL, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2GTH0KF', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 1, 'mcq', E'A researcher wants to determine whether a new fertilizer increases tomato yield. She randomly assigns $30$ tomato plants to receive the new fertilizer and $30$ plants to receive no fertilizer, then measures the yield after $8$ weeks. What type of study is this?', NULL, $lyceon_json$[{"key":"A","text":"An observational study, because the researcher observed the plants growing"},{"key":"B","text":"A survey, because the researcher collected data from the plants"},{"key":"C","text":"An experiment, because the researcher randomly assigned treatments to groups"},{"key":"D","text":"A census, because all plants in the garden were included"}]$lyceon_json$::jsonb, 'C', NULL, E'The defining feature of an experiment is that the researcher imposes a treatment by randomly assigning subjects to groups. Here, the researcher randomly assigned plants to receive the fertilizer or not, making this an experiment. The choice calling it an observational study confuses the act of observing outcomes with the observational study design, which does not impose treatments. The choice calling it a survey misapplies the term, since surveys collect self-reported data from respondents. The choice calling it a census incorrectly assumes all plants in a population were measured, when in fact only a selected group was studied.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2GYOXMU', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 2, 'mcq', E'The mean of $6$ numbers is $19$. When a seventh number is added to the set, the mean of all $7$ numbers becomes $22$. What is the seventh number?', NULL, $lyceon_json$[{"key":"A","text":"$3$"},{"key":"B","text":"$18$"},{"key":"C","text":"$22$"},{"key":"D","text":"$40$"}]$lyceon_json$::jsonb, 'D', NULL, E'The sum of the original $6$ numbers is $6 \\times 19 = 114$. The sum of all $7$ numbers is $7 \\times 22 = 154$. The seventh number is $154 - 114 = 40$. The distractor $3$ results from simply subtracting the two means ($22 - 19$). The distractor $18$ results from using $6 \\times 22 - 6 \\times 19 = 132 - 114 = 18$, incorrectly multiplying the new mean by $6$ instead of $7$. The distractor $22$ results from confusing the new mean with the added number.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2H9LV83', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 1, 'mcq', E'What are all values of $x$ that satisfy the inequality $9x - 36 \\geq 45$?', NULL, $lyceon_json$[{"key":"A","text":"$x \\geq 1$"},{"key":"B","text":"$x \\leq 9$"},{"key":"C","text":"$x \\geq 9$"},{"key":"D","text":"$x \\geq 81$"}]$lyceon_json$::jsonb, 'C', NULL, E'Adding $36$ to both sides gives $9x \\geq 81$. Dividing both sides by $9$ yields $x \\geq 9$. The option $x \\geq 1$ results from incorrectly computing $45 - 36 = 9$ and then dividing $9 \\div 9 = 1$, an arithmetic slip in the subtraction step. The option $x \\leq 9$ has the correct boundary but reverses the inequality direction, a sign error. The option $x \\geq 81$ stops at the intermediate step $9x \\geq 81$ without dividing by $9$, reflecting partial reasoning.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2IBV8UL', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 3, 'mcq', E'$$3x + ky = 14$$
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2IFJZ9G', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 2, 'mcq', E'The function $g(x) = -3(x + 4)^2 + 29$ models a projectile''s height in feet above the ground, where $x$ is the horizontal distance in feet. What is the maximum height, in feet, that the projectile reaches?', NULL, $lyceon_json$[{"key":"A","text":"$-29$"},{"key":"B","text":"$-4$"},{"key":"C","text":"$29$"},{"key":"D","text":"$4$"}]$lyceon_json$::jsonb, 'C', NULL, E'The function is in vertex form $a(x - h)^2 + k$ with $a = -3$, $h = -4$, and $k = 29$. Since $a < 0$, the parabola opens downward and the vertex represents the maximum. The maximum value of $g(x)$ is $k = 29$. The distractor $-29$ results from negating the maximum value. The distractor $-4$ results from identifying the $x$-coordinate of the vertex instead of the maximum output value. The distractor $4$ results from taking the $x$-coordinate of the vertex and dropping the negative sign.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"distractor","error_taxonomy":"misread_question"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2ISGEGS', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 1, 'mcq', E'$$x + 3y = 23$$
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2IUMHCK', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 1, 'mcq', E'In a right triangle, the side opposite angle $\\alpha$ has length $7$ and the hypotenuse has length $19$. What is $\\sin(\\alpha)$?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{7}{19}$"},{"key":"B","text":"$\\frac{19}{7}$"},{"key":"C","text":"$\\frac{12}{19}$"},{"key":"D","text":"$\\frac{7}{12}$"}]$lyceon_json$::jsonb, 'A', NULL, E'The sine of an angle in a right triangle is defined as the ratio of the length of the opposite side to the length of the hypotenuse: $\\sin(\\alpha) = \\frac{\\text{opposite}}{\\text{hypotenuse}} = \\frac{7}{19}$. The fraction $\\frac{19}{7}$ reverses the ratio, giving the cosecant instead of the sine. The value $\\frac{12}{19}$ incorrectly uses $19 - 7 = 12$ as the adjacent side (the Pythagorean theorem, not simple subtraction, determines the adjacent side) and then computes cosine. The value $\\frac{7}{12}$ makes the same adjacent-side error and then computes tangent instead of sine.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2JEZDRB', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 3, 'mcq', E'Two independent random samples were taken from the same large population. Sample 1 had $150$ respondents with a sample proportion of $0.47$ and a margin of error of $\\pm 0.08$. Sample 2 had $600$ respondents with a sample proportion of $0.52$ and a margin of error of $\\pm 0.04$. Which of the following is the best conclusion?', NULL, $lyceon_json$[{"key":"A","text":"The results are inconsistent because the sample proportions differ by $0.05$."},{"key":"B","text":"The results are consistent because the confidence intervals overlap, and the larger sample provides a more precise estimate."},{"key":"C","text":"Sample 1 is more reliable because a smaller sample reduces bias."},{"key":"D","text":"Neither estimate is valid because different samples from the same population should produce identical proportions."}]$lyceon_json$::jsonb, 'B', NULL, E'Sample 1 has a confidence interval of $[0.39, 0.55]$ and Sample 2 has a confidence interval of $[0.48, 0.56]$. These intervals overlap in the range $[0.48, 0.55]$, so the results are consistent with sampling variability. The larger sample (600 respondents) produces a smaller margin of error and therefore a more precise estimate. The distractor claiming inconsistency because proportions differ by $0.05$ confuses natural sampling variability with contradictory results. The distractor calling the smaller sample more reliable reverses the relationship between sample size and precision. The distractor claiming both are invalid because proportions should be identical reflects a fundamental misunderstanding of sampling variability.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2JQCA17', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 3, 'mcq', E'What is the value of $x$ that satisfies $\\frac{4x + 11}{3} - \\frac{x - 5}{2} = x + 8$?', NULL, $lyceon_json$[{"key":"A","text":"$-41$"},{"key":"B","text":"$-11$"},{"key":"C","text":"$11$"},{"key":"D","text":"$21$"}]$lyceon_json$::jsonb, 'B', NULL, E'Multiply every term by the LCD $6$: $2(4x + 11) - 3(x - 5) = 6(x + 8)$. Distribute: $8x + 22 - 3x + 15 = 6x + 48$, so $5x + 37 = 6x + 48$. Subtract $5x$: $37 = x + 48$. Subtract $48$: $x = -11$. The distractor $-41$ arises from a sign error when distributing $-3(x - 5)$ as $-3x - 15$ instead of $-3x + 15$, yielding $5x + 7 = 6x + 48$ and $x = -41$. The distractor $11$ comes from dropping the negative sign in the final step, reporting $11$ instead of $-11$. The distractor $21$ results from not multiplying the second fraction''s numerator by $3$, giving $8x + 22 - x + 5 = 6x + 48$, which simplifies to $7x + 27 = 6x + 48$ and $x = 21$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2K5CYTY', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 1, 'mcq', E'Which expression is equivalent to $11x^4 \\cdot 3x^5$?', NULL, $lyceon_json$[{"key":"A","text":"$14x^9$"},{"key":"B","text":"$33x^{20}$"},{"key":"C","text":"$33x^9$"},{"key":"D","text":"$14x^{20}$"}]$lyceon_json$::jsonb, 'C', NULL, E'To multiply monomials, multiply the coefficients and add the exponents: $11 \\cdot 3 = 33$ and $x^4 \\cdot x^5 = x^{4+5} = x^9$, giving $33x^9$. The distractor $14x^9$ results from adding the coefficients ($11 + 3 = 14$) instead of multiplying them. The distractor $33x^{20}$ results from multiplying the exponents ($4 \\times 5 = 20$) instead of adding them. The distractor $14x^{20}$ combines both errors — adding the coefficients and multiplying the exponents.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2KKGNHX', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 1, 'grid_in', E'If $f(x) = 3x^2 - 7x + 11$, what is the value of $f(-2)$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '37', ARRAY['37'], E'Substituting $x = -2$ into the function: $f(-2) = 3(-2)^2 - 7(-2) + 11 = 3(4) + 14 + 11 = 12 + 14 + 11 = 37$.', NULL, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2KS2XY7', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 1, 'grid_in', E'A data set consists of the values $14$, $23$, $9$, $31$, and $23$. What is the median of this data set?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '23', ARRAY['23'], E'Arranging the values in ascending order gives $9, 14, 23, 23, 31$. The median is the middle value of an odd-numbered data set, which is the third value: $23$.', NULL, NULL, 'draft', 1, 30, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2LLILU4', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 3, 'mcq', E'A grain silo consists of a right circular cylinder with radius $6$ meters and height $13$ meters, topped by a hemisphere with the same radius. What is the total volume of the silo?', NULL, $lyceon_json$[{"key":"A","text":"$468\\pi$ cubic meters"},{"key":"B","text":"$540\\pi$ cubic meters"},{"key":"C","text":"$612\\pi$ cubic meters"},{"key":"D","text":"$756\\pi$ cubic meters"}]$lyceon_json$::jsonb, 'C', NULL, E'The total volume is the sum of the cylinder volume and the hemisphere volume. The cylinder volume is $V_{\\text{cyl}} = \\pi r^2 h = \\pi(6)^2(13) = 468\\pi$. The hemisphere volume is half the volume of a sphere: $V_{\\text{hemi}} = \\frac{1}{2} \\cdot \\frac{4}{3}\\pi r^3 = \\frac{2}{3}\\pi(6)^3 = \\frac{2}{3}\\pi(216) = 144\\pi$. The total is $468\\pi + 144\\pi = 612\\pi$ cubic meters. The value $468\\pi$ accounts for only the cylinder and omits the hemisphere entirely. The value $540\\pi$ results from using the cone volume formula $\\frac{1}{3}\\pi r^2 r = \\frac{1}{3}\\pi(36)(6) = 72\\pi$ for the top portion instead of the hemisphere formula, giving $468\\pi + 72\\pi$. The value $756\\pi$ uses the full sphere volume $\\frac{4}{3}\\pi(216) = 288\\pi$ instead of half of it, giving $468\\pi + 288\\pi$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2N5K3W8', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 2, 'mcq', E'At what points do the graphs of $y = x^2 - 9x + 14$ and $y = -2x + 2$ intersect in the $xy$-plane?', NULL, $lyceon_json$[{"key":"A","text":"$(3, -4)$ and $(4, -6)$"},{"key":"B","text":"$(3, 4)$ and $(4, 6)$"},{"key":"C","text":"$(2, -2)$ and $(7, -12)$"},{"key":"D","text":"$(3, -4)$ only"}]$lyceon_json$::jsonb, 'A', NULL, E'Setting the expressions equal: $x^2 - 9x + 14 = -2x + 2$, which simplifies to $x^2 - 7x + 12 = 0$. Factoring gives $(x - 3)(x - 4) = 0$, so $x = 3$ or $x = 4$. Substituting into $y = -2x + 2$: when $x = 3$, $y = -4$; when $x = 4$, $y = -6$. The intersection points are $(3, -4)$ and $(4, -6)$. The distractor $(3, 4)$ and $(4, 6)$ results from dropping the negative sign when computing the $y$-values. The distractor $(2, -2)$ and $(7, -12)$ results from setting the quadratic equal to zero ($x^2 - 9x + 14 = 0$) instead of equating it to the linear expression, finding $x = 2$ and $x = 7$, then substituting into the line. The distractor $(3, -4)$ only results from finding only one of the two solutions.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2OEXJH4', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 2, 'grid_in', E'At a cafe, $4$ bagels and $3$ pastries cost a total of $\\$43$. At the same cafe, $2$ bagels and $3$ pastries cost a total of $\\$29$. What is the total cost, in dollars, of $7$ bagels?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '49', ARRAY['49'], E'Let $b$ represent the cost of one bagel and $p$ represent the cost of one pastry. The system is $4b + 3p = 43$ and $2b + 3p = 29$. Subtracting the second equation from the first eliminates $p$: $(4b + 3p) - (2b + 3p) = 43 - 29$, giving $2b = 14$, so $b = 7$. The cost of $7$ bagels is $7 \\times 7 = 49$ dollars.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2OXKGQ1', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 3, 'mcq', E'A pharmaceutical company tested a new medication by randomly assigning $500$ volunteers to receive the medication and $500$ to receive a placebo. The study found that the medication group had a $23\\%$ reduction in symptoms compared to the placebo group, with $p < 0.03$. However, $78\\%$ of participants in the medication group correctly guessed they were receiving the medication rather than the placebo. Which of the following best describes a limitation of this study?', NULL, $lyceon_json$[{"key":"A","text":"The sample size of $1{,}000$ is too small to detect a $23\\%$ reduction in symptoms."},{"key":"B","text":"The study lacks a control group, making it impossible to attribute the reduction to the medication."},{"key":"C","text":"Participants' awareness of their treatment assignment may have introduced expectation bias that inflated the observed benefit, compromising the blinding."},{"key":"D","text":"A $p$-value less than $0.03$ indicates the results are not statistically significant."}]$lyceon_json$::jsonb, 'C', NULL, E'Although the study was a randomized controlled experiment, effective blinding requires that participants cannot distinguish between the treatment and placebo. Since $78\\%$ of medication recipients correctly identified their assignment, the blinding was compromised. This awareness can introduce expectation bias: participants who believe they are receiving the real medication may report greater symptom improvement regardless of the medication''s actual efficacy, inflating the observed $23\\%$ reduction. The claim that the sample is too small is incorrect because the study did detect a statistically significant effect. The claim that there is no control group is wrong because the placebo group serves as the control. The claim that $p < 0.03$ is not statistically significant misinterprets the $p$-value, since $0.03$ is below the conventional $0.05$ significance threshold.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 100, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2Q03CD3', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 3, 'mcq', E'Line $m$ has the equation $3x - 7y = 28$. Line $n$ is perpendicular to line $m$ and passes through the point $(6, -1)$. What is the $y$-intercept of line $n$?', NULL, $lyceon_json$[{"key":"A","text":"$-15$"},{"key":"B","text":"$-4$"},{"key":"C","text":"$13$"},{"key":"D","text":"$14$"}]$lyceon_json$::jsonb, 'C', NULL, E'Rewrite line $m$ in slope-intercept form: $3x - 7y = 28$ becomes $y = \\frac{3}{7}x - 4$, so the slope of $m$ is $\\frac{3}{7}$. The slope of a perpendicular line is the negative reciprocal: $-\\frac{7}{3}$. Using point-slope form with $(6, -1)$: $y - (-1) = -\\frac{7}{3}(x - 6)$, so $y + 1 = -\\frac{7}{3}x + 14$, giving $y = -\\frac{7}{3}x + 13$. The $y$-intercept is $13$. The distractor $-15$ results from using $\\frac{7}{3}$ (positive) instead of $-\\frac{7}{3}$ as the perpendicular slope, leading to $y = \\frac{7}{3}x - 14 - 1 = \\frac{7}{3}x - 15$. The distractor $-4$ comes from simply reading the $y$-intercept of line $m$ without finding line $n$. The distractor $14$ arises from forgetting to subtract $1$ from both sides, stopping at $y + 1 = -\\frac{7}{3}x + 14$ and reporting $14$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2S4NJVT', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 3, 'mcq', E'The function $h(x) = 3x + b$, where $b$ is a constant, has the property that $h(h(2)) = 50$. What is the value of $b$?', NULL, $lyceon_json$[{"key":"A","text":"$8$"},{"key":"B","text":"$16$"},{"key":"C","text":"$32$"},{"key":"D","text":"$44$"}]$lyceon_json$::jsonb, 'A', NULL, E'First, $h(2) = 3(2) + b = 6 + b$. Then $h(h(2)) = h(6 + b) = 3(6 + b) + b = 18 + 3b + b = 18 + 4b$. Setting this equal to $50$: $18 + 4b = 50$, so $4b = 32$ and $b = 8$. Verification: $h(2) = 14$, $h(14) = 50$. The distractor $16$ results from not distributing the $3$ over $(6 + b)$, computing $h(6 + b) = 18 + 2b$ instead of $18 + 4b$, which gives $2b = 32$ and $b = 16$. The distractor $32$ comes from correctly reaching $4b = 32$ but reporting the product $32$ instead of dividing to find $b$. The distractor $44$ results from solving $h(2) = 50$ directly (i.e., $6 + b = 50$, so $b = 44$), treating the problem as a single application of $h$ rather than a composition.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2TQYUCH', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 3, 'grid_in', E'The scores of $8$ students on a quiz are $62$, $71$, $74$, $78$, $83$, $85$, $91$, and $96$. What is the interquartile range of the scores?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '15.5', ARRAY['31/2', '15.5'], E'The data is already sorted: $62, 71, 74, 78, 83, 85, 91, 96$. The lower half is $62, 71, 74, 78$, so $Q_1 = \\frac{71 + 74}{2} = 72.5$. The upper half is $83, 85, 91, 96$, so $Q_3 = \\frac{85 + 91}{2} = 88$. The interquartile range is $Q_3 - Q_1 = 88 - 72.5 = 15.5$. A common error is computing the full range ($96 - 62 = 34$) instead of the interquartile range. Another error is using only single values for $Q_1$ and $Q_3$ instead of averaging the two middle values of each half.', NULL, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2U2OM5D', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 2, 'grid_in', E'A circle has radius $11$. A central angle subtends an arc of length $\\frac{11\\pi}{3}$. What is the measure of the central angle, in degrees?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '60', ARRAY['60'], E'The arc length formula is $s = r\\theta$, where $s$ is the arc length, $r$ is the radius, and $\\theta$ is the central angle in radians. Substituting: $\\frac{11\\pi}{3} = 11\\theta$, so $\\theta = \\frac{\\pi}{3}$ radians. Converting to degrees: $\\frac{\\pi}{3} \\times \\frac{180°}{\\pi} = 60°$. A common error is to forget to convert from radians to degrees and report $\\frac{\\pi}{3}$ or approximately $1.05$. Another error is to confuse the arc length formula with the sector area formula, leading to an incorrect angle.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2UE49LP', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 2, 'mcq', E'In triangle $PQR$, the measure of angle $P$ is $47°$ and the measure of angle $Q$ is $68°$. What is the measure, in degrees, of the exterior angle at vertex $R$?', NULL, $lyceon_json$[{"key":"A","text":"$65$"},{"key":"B","text":"$112$"},{"key":"C","text":"$115$"},{"key":"D","text":"$133$"}]$lyceon_json$::jsonb, 'C', NULL, E'The exterior angle of a triangle equals the sum of the two non-adjacent interior angles. Therefore the exterior angle at vertex R equals $47° + 68° = 115°$. Alternatively, the interior angle at R is $180° - 47° - 68° = 65°$, and the exterior angle is $180° - 65° = 115°$. The value $65°$ is only the interior angle at R, not the exterior angle. The value $112°$ results from computing $180° - 68°$, which gives the supplement of angle Q rather than the exterior angle at R. The value $133°$ comes from a computational error such as $180° - 47° = 133°$, which is the supplement of angle P.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"misread_question"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2UIG04Z', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 3, 'grid_in', E'A shipping company packs small crates weighing $3$ pounds each and large crates weighing $11$ pounds each. Every shipment must include at least $5$ large crates, and the total weight of the shipment cannot exceed $200$ pounds. What is the maximum number of small crates that can be included in a single shipment?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '48', ARRAY['48'], E'To maximize the number of small crates, minimize the number of large crates. The minimum is $5$ large crates, contributing $5 \\times 11 = 55$ pounds. The remaining weight capacity is $200 - 55 = 145$ pounds. Each small crate weighs $3$ pounds, so the maximum number of small crates is $\\lfloor 145 \\div 3 \\rfloor = \\lfloor 48.\\overline{3} \\rfloor = 48$. Verification: $3(48) + 11(5) = 144 + 55 = 199 \\leq 200$, and $3(49) + 11(5) = 147 + 55 = 202 > 200$, confirming $48$ is the maximum.', NULL, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2UJTMSY', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 1, 'grid_in', E'What is the value of $x$ in the equation $4x + 29 = 57$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '7', ARRAY['7'], E'Subtract $29$ from both sides to get $4x = 28$. Divide both sides by $4$ to find $x = 7$.', NULL, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2UPDVSX', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 2, 'mcq', E'What value of $x$ satisfies the equation $\\frac{5(x - 3)}{2} = x + 9$?', NULL, $lyceon_json$[{"key":"A","text":"$1$"},{"key":"B","text":"$6$"},{"key":"C","text":"$11$"},{"key":"D","text":"$33$"}]$lyceon_json$::jsonb, 'C', NULL, E'Multiply both sides by $2$: $5(x - 3) = 2(x + 9)$. Distribute: $5x - 15 = 2x + 18$. Subtract $2x$ from both sides: $3x - 15 = 18$. Add $15$: $3x = 33$. Divide by $3$: $x = 11$. The distractor $1$ results from a sign error when distributing $5(x - 3)$ as $5x + 15$, leading to $3x = 3$. The distractor $6$ comes from failing to multiply the right side by $2$, giving $5x - 15 = x + 9$ and then $4x = 24$. The distractor $33$ is the intermediate value $3x = 33$ reported without dividing by $3$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2V03464', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 2, 'mcq', E'What is the equation of the line that passes through the points $(2, 11)$ and $(5, 23)$?', NULL, $lyceon_json$[{"key":"A","text":"$y = 4x - 3$"},{"key":"B","text":"$y = 4x + 3$"},{"key":"C","text":"$y = 3x + 5$"},{"key":"D","text":"$y = 12x - 13$"}]$lyceon_json$::jsonb, 'B', NULL, E'The slope is $\\frac{23 - 11}{5 - 2} = \\frac{12}{3} = 4$. Using point-slope form with $(2, 11)$: $y - 11 = 4(x - 2)$, so $y = 4x - 8 + 11 = 4x + 3$. The distractor $y = 4x - 3$ results from a sign error when computing the $y$-intercept as $8 - 11 = -3$ instead of $11 - 8 = 3$. The distractor $y = 3x + 5$ arises from using the denominator of the slope fraction ($3$) as the slope instead of the quotient $4$, then computing $b = 11 - 3(2) = 5$. The distractor $y = 12x - 13$ comes from using the rise $12$ directly as the slope without dividing by the run, then computing $b = 11 - 12(2) = -13$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2V1P3HB', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 1, 'grid_in', E'A factory produces $91$ widgets every $7$ hours. At this constant rate, how many widgets does the factory produce in $3$ hours?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '39', ARRAY['39'], E'The production rate is $\\frac{91}{7} = 13$ widgets per hour. In $3$ hours, the factory produces $13 \\times 3 = 39$ widgets.', NULL, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2VCSDA2', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 2, 'mcq', E'Which expression is equivalent to $(4x - 9)(2x + 7)$?', NULL, $lyceon_json$[{"key":"A","text":"$8x^2 - 10x - 63$"},{"key":"B","text":"$8x^2 + 10x - 63$"},{"key":"C","text":"$8x^2 + 46x - 63$"},{"key":"D","text":"$8x^2 + 10x + 63$"}]$lyceon_json$::jsonb, 'B', NULL, E'Applying FOIL: $(4x)(2x) = 8x^2$, $(4x)(7) = 28x$, $(-9)(2x) = -18x$, and $(-9)(7) = -63$. Combining the middle terms gives $28x - 18x = 10x$, so the product is $8x^2 + 10x - 63$. The distractor $8x^2 - 10x - 63$ arises from reversing the signs of the middle terms, yielding $-28x + 18x = -10x$. The distractor $8x^2 + 46x - 63$ arises from adding rather than subtracting the middle-term magnitudes ($28 + 18 = 46$). The distractor $8x^2 + 10x + 63$ results from incorrectly treating the constant term as positive.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2VM2FIE', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 1, 'mcq', E'Two parallel lines are cut by a transversal. One of the angles formed at the first intersection measures $137°$. What is the measure, in degrees, of the co-interior angle on the same side of the transversal at the second intersection?', NULL, $lyceon_json$[{"key":"A","text":"$43$"},{"key":"B","text":"$53$"},{"key":"C","text":"$90$"},{"key":"D","text":"$137$"}]$lyceon_json$::jsonb, 'A', NULL, E'Co-interior angles (also called consecutive interior angles or same-side interior angles) formed by parallel lines and a transversal are supplementary, meaning they sum to $180°$. Therefore the unknown angle is $180° - 137° = 43°$. The answer $53°$ results from a subtraction error. The answer $90°$ incorrectly assumes a right angle. The answer $137°$ confuses co-interior angles with corresponding angles, which are equal rather than supplementary.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2VNJBDR', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 1, 'mcq', E'A book originally costs $\\$65$. The bookstore applies a $40\\%$ discount. What is the sale price of the book?', NULL, $lyceon_json$[{"key":"A","text":"$\\$25$"},{"key":"B","text":"$\\$26$"},{"key":"C","text":"$\\$39$"},{"key":"D","text":"$\\$91$"}]$lyceon_json$::jsonb, 'C', NULL, E'A $40\\%$ discount on $\\$65$ is $0.40 \\times 65 = \\$26$. The sale price is $65 - 26 = \\$39$. The distractor $\\$25$ results from subtracting $40$ from $65$ instead of computing $40\\%$ of $65$. The distractor $\\$26$ is the discount amount itself, not the sale price. The distractor $\\$91$ results from adding the discount to the original price instead of subtracting it.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2VQ71S2', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 3, 'grid_in', E'For what value of $c$ does the system of equations $y = 2x^2 - 11x + c$ and $y = 3x - 7$ have exactly one real solution?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '35/2', ARRAY['35/2', '17.5'], E'Setting the equations equal gives $2x^2 - 11x + c = 3x - 7$, which rearranges to $2x^2 - 14x + (c + 7) = 0$. For this quadratic to have exactly one real solution, its discriminant must equal zero. The discriminant is $(-14)^2 - 4(2)(c + 7) = 196 - 8(c + 7) = 196 - 8c - 56 = 140 - 8c$. Setting $140 - 8c = 0$ gives $c = \\frac{140}{8} = \\frac{35}{2}$.', NULL, NULL, 'draft', 1, 120, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2VY92B0', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 3, 'grid_in', E'At a veterinary clinic, $37\\%$ of the animals are dogs, $28\\%$ are cats, and the rest are other animals. Among dogs, $43\\%$ have been vaccinated this year. Among cats, $61\\%$ have been vaccinated. Among other animals, $22\\%$ have been vaccinated. If an animal is selected at random and found to have been vaccinated this year, what is the probability, to the nearest hundredth, that it is a cat?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '0.42', ARRAY['21/50', '0.42', '.42'], E'The percentage of other animals is $100\\% - 37\\% - 28\\% = 35\\%$. Using the law of total probability, the overall vaccination rate is $P(V) = 0.37 \\times 0.43 + 0.28 \\times 0.61 + 0.35 \\times 0.22 = 0.1591 + 0.1708 + 0.077 = 0.4069$. By Bayes'' theorem, $P(\\text{cat} \\mid V) = \\frac{0.28 \\times 0.61}{0.4069} = \\frac{0.1708}{0.4069} \\approx 0.4198$, which rounds to $0.42$.', NULL, NULL, 'draft', 1, 110, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2WJWYED', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 1, 'mcq', E'A box contains $13$ red buttons, $8$ blue buttons, and $4$ green buttons. If one button is selected at random, what is the probability that it is blue?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{8}{25}$"},{"key":"B","text":"$\\frac{8}{13}$"},{"key":"C","text":"$\\frac{4}{25}$"},{"key":"D","text":"$\\frac{8}{17}$"}]$lyceon_json$::jsonb, 'A', NULL, E'The total number of buttons is $13 + 8 + 4 = 25$. The probability of selecting a blue button is the number of blue buttons divided by the total: $\\frac{8}{25}$. The distractor $\\frac{8}{13}$ results from dividing the blue count by the red count instead of the total. The distractor $\\frac{4}{25}$ uses the green button count in the numerator instead of the blue count. The distractor $\\frac{8}{17}$ divides by the number of non-blue buttons ($13 + 4 = 17$) instead of the total, reflecting a misunderstanding of the sample space.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2XXO9AH', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 1, 'grid_in', E'If $f(x) = 9x - 17$, what is the value of $f(7)$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '46', ARRAY['46'], E'Substitute $x = 7$ into the function: $f(7) = 9(7) - 17 = 63 - 17 = 46$.', NULL, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2YWQWW9', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 2, 'mcq', E'A polling company surveyed $450$ randomly selected voters and found that $62\\%$ favored a ballot measure, with a margin of error of $\\pm 4.3\\%$. A newspaper reported that a majority of voters favor the measure. Which of the following best evaluates the newspaper''s claim?', NULL, $lyceon_json$[{"key":"A","text":"The claim is supported because the entire confidence interval is above $50\\%$."},{"key":"B","text":"The claim is not supported because the margin of error could reduce the true percentage below $50\\%$."},{"key":"C","text":"The claim is supported only if the sample size is increased to at least $1{,}000$."},{"key":"D","text":"The claim cannot be evaluated without knowing the confidence level used."}]$lyceon_json$::jsonb, 'A', NULL, E'The confidence interval is $62\\% - 4.3\\% = 57.7\\%$ to $62\\% + 4.3\\% = 66.3\\%$. Since the entire interval lies above $50\\%$, the data support the claim that a majority favors the measure. The distractor stating the margin could reduce the percentage below $50\\%$ reflects an arithmetic error: $62\\% - 4.3\\% = 57.7\\%$, which is still above $50\\%$. The distractor requiring a larger sample size introduces an irrelevant condition, since the existing margin of error already resolves the question. The distractor claiming the confidence level is needed overlooks that the margin of error already incorporates the confidence level in its calculation.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW23QRWMC', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 1, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Every spring, the municipal gardens committee _______ a different local artist to design the flower arrangements displayed along the city''s central promenade.', $lyceon_json$[{"key":"A","text":"commission"},{"key":"B","text":"have commissioned"},{"key":"C","text":"commissions"},{"key":"D","text":"are commissioning"}]$lyceon_json$::jsonb, 'C', NULL, E'The subject is ''the municipal gardens committee,'' a singular collective noun requiring a singular verb. The option ''commissions'' provides the correct third-person singular present-tense form to match the habitual action indicated by ''Every spring.'' The option ''commission'' is a bare plural form that does not agree with the singular subject. The option ''have commissioned'' uses a plural auxiliary (''have'') that disagrees with the singular subject and shifts to the present perfect without contextual justification. The option ''are commissioning'' uses a plural auxiliary (''are'') that disagrees with the singular subject.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW26LDZL1', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 1, 'mcq', E'As used in the text, what does the word "sustained" most nearly mean?', E'Marine biologists studying the kelp forests off the coast of Tasmania found that the ecosystem had sustained considerable damage from rising ocean temperatures. The researchers noted that without intervention, the forests would likely collapse within a decade, depriving hundreds of species of their primary habitat.', $lyceon_json$[{"key":"A","text":"endured"},{"key":"B","text":"nourished"},{"key":"C","text":"prolonged"},{"key":"D","text":"championed"}]$lyceon_json$::jsonb, 'A', NULL, E'In the passage, "sustained" describes the ecosystem having undergone or received damage, making "endured" the correct choice because it conveys the meaning of having experienced something harmful. "Nourished" means to provide sustenance or food, which contradicts the context of damage. "Prolonged" means to extend in duration, which does not fit the grammatical construction of receiving damage. "Championed" means to advocate for a cause, which is entirely unrelated to the act of incurring harm.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"vocab_context_error"},"C":{"role":"distractor","error_taxonomy":"vocab_context_error"},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
