INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2820M4L', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 2, 'mcq', E'Which choice most logically completes the text?', E'Sociologist Nkechi Okafor studied 23 mid-sized American cities that adopted participatory budgeting — a process in which residents directly vote on how to allocate a portion of public funds. Okafor found that in the first two years of implementation, voter turnout in participatory budgeting elections was dominated by residents who already participated in conventional elections at high rates. However, by the fourth year of the programs, participation among previously disengaged demographic groups — particularly renters, younger adults, and non-native English speakers — increased substantially, while participation among the initially dominant groups remained stable. Okafor suggested that these findings indicate that participatory budgeting ________', $lyceon_json$[{"key":"A","text":"can broaden civic engagement over time, though it initially attracts those who are already civically active."},{"key":"B","text":"is less effective than conventional elections at ensuring equitable representation of all demographic groups."},{"key":"C","text":"causes previously active voters to lose interest in civic participation as new groups become involved."},{"key":"D","text":"functions best when restricted to cities with populations under 200,000 residents."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage describes a pattern in which participatory budgeting initially attracted already-active voters but over four years drew in previously disengaged groups, with original participation levels holding steady. The option about broadening civic engagement over time while initially attracting the already active logically follows from this trajectory. The option claiming participatory budgeting is less effective than conventional elections contradicts the passage''s evidence of expanding participation. The option about previously active voters losing interest contradicts the explicit finding that their participation remained stable. The option about city population size introduces a restriction the passage never discusses — the study examined mid-sized cities but drew no conclusion about size-based effectiveness.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW29P2LL4', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 2, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'In 1879, the archaeologist Flinders Petrie developed a technique called sequence _______ allowed researchers to establish relative chronologies for artifacts even when absolute dates were unavailable.', $lyceon_json$[{"key":"A","text":"dating, it"},{"key":"B","text":"dating it"},{"key":"C","text":"dating that"},{"key":"D","text":"dating. It"}]$lyceon_json$::jsonb, 'C', NULL, E'The sentence requires a relative pronoun to introduce a restrictive relative clause modifying ''a technique called sequence dating.'' The option using ''that'' correctly links the noun phrase to the clause ''allowed researchers to establish relative chronologies.'' The option ''dating, it'' creates a comma splice joining two independent clauses with only a comma. The option ''dating it'' fuses two independent clauses with no punctuation or conjunction, creating a run-on. The option ''dating. It'' splits the sentence in a way that leaves ''a technique called sequence dating'' as a fragment rather than a complete clause.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"sentence_boundary_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
