INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2ADL6XC', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'In a 2021 study of circadian rhythms in nocturnal primates, researchers at the Montpellier Primate Center found that neither the aye-aye nor the slow _______ any significant change in melatonin production when exposed to dim red light during normal sleeping hours.', $lyceon_json$[{"key":"A","text":"loris exhibit"},{"key":"B","text":"loris exhibits"},{"key":"C","text":"lorises exhibit"},{"key":"D","text":"lorises exhibits"}]$lyceon_json$::jsonb, 'B', NULL, E'In a ''neither...nor'' construction, the verb agrees with the nearer subject. Here the nearer subject is ''the slow loris,'' which is singular, so the verb must be the singular ''exhibits.'' The option ''loris exhibits'' correctly pairs the singular noun with the singular verb form. The option ''loris exhibit'' uses the singular noun but the plural verb form ''exhibit,'' violating subject-verb agreement. The option ''lorises exhibit'' changes the noun to plural, misrepresenting the passage''s reference to the species in the singular and, while the plural noun and plural verb would agree with each other, the construction ''neither the aye-aye nor the slow lorises'' alters the intended meaning. The option ''lorises exhibits'' pairs a plural noun with a singular verb, creating a straightforward agreement error.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2BF7QKA', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 1, 'mcq', E'Which choice best states the main idea of the text?', E'Researchers at the University of Tromsø recently discovered that Arctic bumblebees can maintain thoracic temperatures above 30°C even when ambient air temperatures drop to 5°C. The bees accomplish this by rapidly vibrating their flight muscles before takeoff, a process known as pre-flight thermogenesis. This capacity allows them to forage during the brief Arctic summer when most other pollinators remain inactive, giving them near-exclusive access to early-blooming wildflowers such as purple saxifrage.', $lyceon_json$[{"key":"A","text":"Arctic bumblebees have a unique thermoregulatory ability that enables them to forage in cold conditions other pollinators cannot tolerate."},{"key":"B","text":"Purple saxifrage is the primary food source for Arctic bumblebees during the short Arctic summer."},{"key":"C","text":"Pre-flight thermogenesis is a process that all bumblebee species use to survive in cold environments."},{"key":"D","text":"Researchers at the University of Tromsø study insect behavior in extreme climates around the world."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage describes how Arctic bumblebees use pre-flight thermogenesis to maintain high body temperatures in cold conditions, allowing them to forage when other pollinators cannot. The option stating that Arctic bumblebees have a unique thermoregulatory ability enabling cold-weather foraging captures this central idea. The option about purple saxifrage distorts a supporting detail — the flower is mentioned as one example of what they access, not as their primary food source. The option claiming all bumblebee species use pre-flight thermogenesis overgeneralizes beyond what the passage states, which discusses only Arctic bumblebees. The option about researchers studying insect behavior worldwide misrepresents the scope of the passage, which focuses on one specific finding about Arctic bumblebees.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"detail_misread"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2CARA4K', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 2, 'mcq', E'As used in the text, what does the word "compound" most nearly mean?', E'Ethnomusicologist Jara Veltheim argues that the global dissemination of streaming platforms has begun to compound longstanding inequities in music licensing. Independent artists in West Africa, she notes, already received a fraction of the royalties earned by major-label performers; the algorithmic curation systems now prevalent on these platforms further marginalize their work by directing listeners toward commercially dominant catalogs.', $lyceon_json$[{"key":"A","text":"intensify"},{"key":"B","text":"merge"},{"key":"C","text":"calculate"},{"key":"D","text":"settle"}]$lyceon_json$::jsonb, 'A', NULL, E'Here "compound" means to make something already problematic even worse, so "intensify" correctly captures the sense of worsening existing inequities. "Merge" means to combine separate things into one, which does not describe the act of aggravating a pre-existing condition. "Calculate" refers to mathematical computation, a meaning of "compound" related to interest that has no relevance to the passage''s discussion of inequity. "Settle" means to resolve or bring to rest, which is the opposite of what the passage describes happening to the inequities.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"vocab_context_error"},"C":{"role":"distractor","error_taxonomy":"vocab_context_error"},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2E8U0E4', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 3, 'mcq', E'Which choice best describes the primary purpose of the text?', E'In a 2023 study, materials scientist Priya Chandrasekaran subjected bismuth ferrite thin films to controlled oxygen vacancies and observed that the material''s ferroelectric polarization could be reversibly toggled between two stable states at room temperature. Whereas prior research required cryogenic conditions to achieve similar switching behavior in multiferroic compounds, Chandrasekaran''s technique operates within a range feasible for commercial device integration. Her findings suggest that oxygen-vacancy engineering may provide a pathway to non-volatile memory elements that combine the density advantages of ferroelectric storage with the energy efficiency of magnetic switching.', $lyceon_json$[{"key":"A","text":"To describe a research finding that addresses a practical obstacle encountered in earlier work on a class of materials."},{"key":"B","text":"To argue that oxygen-vacancy engineering is the only viable method for producing non-volatile memory devices."},{"key":"C","text":"To compare the ferroelectric and magnetic properties of bismuth ferrite with those of other multiferroic compounds."},{"key":"D","text":"To explain why cryogenic conditions are necessary for switching behavior in most multiferroic materials."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage presents Chandrasekaran''s finding that oxygen-vacancy engineering enables room-temperature polarization switching, directly addressing the practical limitation of earlier work that required cryogenic conditions, so the choice about describing a finding that addresses a practical obstacle is correct. The choice claiming oxygen-vacancy engineering is the only viable method overstates the passage, which says it "may provide a pathway" without excluding other approaches. The choice about comparing bismuth ferrite with other multiferroic compounds is wrong because the passage focuses on Chandrasekaran''s specific technique rather than systematically comparing materials. The choice about explaining why cryogenic conditions are necessary is wrong because the passage mentions cryogenic requirements only as a prior limitation, not as its central explanatory purpose.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2F4A7ZX', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The Svalbard Global Seed Vault, carved into the permafrost of a Norwegian mountainside, stores duplicate samples of seeds from gene banks worldwide. _______ nearly one million seed varieties from every recognized nation with an active agricultural program, the vault serves as an insurance policy against the catastrophic loss of crop diversity.', $lyceon_json$[{"key":"A","text":"Holding"},{"key":"B","text":"Having held"},{"key":"C","text":"It holds"},{"key":"D","text":"To hold"}]$lyceon_json$::jsonb, 'A', NULL, E'The blank begins a participial phrase that modifies ''the vault,'' the subject of the main clause ''the vault serves as an insurance policy.'' The present participle ''Holding'' correctly forms a participial phrase describing a simultaneous, ongoing state—the vault currently holds these seeds and currently serves as insurance. The option ''Having held'' implies the holding occurred before the serving, but the vault still holds the seeds now, so a completed-action participle misrepresents the timeline. The option ''It holds'' creates a comma splice: ''It holds...program'' would be an independent clause joined to ''the vault serves...'' by only a comma, with no coordinating conjunction. The option ''To hold'' creates an infinitive phrase suggesting purpose (''in order to hold''), which distorts the meaning—the vault does not serve as insurance for the purpose of holding seeds; rather, because it holds seeds, it serves as insurance.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2G4JMZO', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 1, 'mcq', E'Which choice best describes the function of the underlined sentence in the text?', E'The fruit fly Drosophila melanogaster has been a cornerstone of genetics research for over a century. Its short generation time — roughly twelve days from egg to adult — allows scientists to observe hereditary patterns across many generations in a matter of months. _More recently, researchers have employed the organism to study neurodegenerative diseases, exploiting the surprising genetic overlap between flies and humans._ This expansion of the fly''s research role demonstrates how a single model organism can illuminate questions far beyond its original purpose.', $lyceon_json$[{"key":"A","text":"It introduces a newer application of an organism traditionally used for a different purpose."},{"key":"B","text":"It provides a historical overview of the fruit fly's role in scientific experimentation."},{"key":"C","text":"It challenges the assumption that fruit flies are useful in genetics research."},{"key":"D","text":"It explains why fruit flies reproduce more quickly than other model organisms."}]$lyceon_json$::jsonb, 'A', NULL, E'The underlined sentence shifts from the fruit fly''s traditional genetics role to its newer application in neurodegenerative disease research, so the choice stating it introduces a newer application of an organism traditionally used for a different purpose is correct. The choice about a historical overview is wrong because the underlined sentence focuses on a recent development, not a chronological survey. The choice about challenging the assumption that fruit flies are useful in genetics misrepresents the passage, which affirms rather than questions their research value. The choice about reproduction speed is wrong because the underlined sentence discusses a new research application, not the organism''s reproductive rate.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2HQKAJX', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 1, 'mcq', E'A student is writing a brief article about the Cumberland Plateau salamander for a nature magazine. The student wants to introduce the species to readers who may be unfamiliar with it. Which choice most effectively uses relevant information from the notes to accomplish this goal?', E'Notes:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2I0UGZB', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 2, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Although several archaeobotanists had examined pollen records from the Qinghai-Tibet Plateau, none of _______ identified the high concentration of ancient buckwheat grains that Dr. Liang Xu''s team discovered in 2019.', $lyceon_json$[{"key":"A","text":"they"},{"key":"B","text":"their"},{"key":"C","text":"them"},{"key":"D","text":"those"}]$lyceon_json$::jsonb, 'C', NULL, E'The pronoun follows the preposition ''of,'' which requires the objective case. The option ''them'' is the correct objective-case pronoun referring to ''several archaeobotanists.'' The option ''they'' is a subjective-case pronoun and cannot serve as the object of a preposition. The option ''their'' is a possessive pronoun, which is grammatically incompatible as the object of ''of'' in this construction. The option ''those'' is a demonstrative pronoun that could work with a following noun (''those researchers'') but stands alone here without a referent noun, making it grammatically incomplete in this context.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2IEX4HP', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The deep-sea anglerfish Melanocetus johnsonii uses a bioluminescent lure to attract prey in the lightless depths of the ocean. The lure, which extends from a modified dorsal _______ contains symbiotic bacteria that produce the characteristic blue-green glow through a chemical reaction involving the enzyme luciferase.', $lyceon_json$[{"key":"A","text":"spine;"},{"key":"B","text":"spine,"},{"key":"C","text":"spine"},{"key":"D","text":"spine—"}]$lyceon_json$::jsonb, 'B', NULL, E'The clause ''which extends from a modified dorsal spine'' is a nonrestrictive relative clause set off by commas. Since the opening comma appears before ''which,'' a closing comma must follow ''spine'' to complete the pair and return to the main clause (''contains symbiotic bacteria...''). The option with a semicolon after ''spine'' incorrectly treats what follows the nonrestrictive clause as a separate independent clause, but ''The lure... contains'' is one continuous sentence. Omitting punctuation after ''spine'' fails to close the nonrestrictive clause, creating a grammatical error. A dash after ''spine'' would require a matching dash before ''which'' rather than the comma already present in the passage, producing mismatched punctuation.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"sentence_boundary_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2JNCBJW', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 3, 'mcq', E'Which quotation from a research article would, if incorporated into the text, most effectively serve as evidence supporting Halperin''s claim about municipal composting programs?', E'Urban policy analyst David Halperin contends that municipal composting programs, despite their environmental promise, often fail to achieve projected waste-diversion rates because they underestimate the behavioral friction involved in household participation. Halperin argues that programs treating composting as a simple opt-in service overlook the sustained effort required: sorting organic waste consistently, tolerating odors, and managing collection schedules. He concludes that without integrating behavioral design principles — such as default enrollment and curbside pickup — composting programs will remain underutilized regardless of public environmental sentiment.', $lyceon_json$[{"key":"A","text":"\"Surveyed households reported strong pro-environmental attitudes, yet only 17 percent of those enrolled in voluntary composting programs maintained consistent participation beyond the initial three-month period.\""},{"key":"B","text":"\"Cities that invested in larger composting facilities saw a proportional increase in the total volume of organic waste processed annually.\""},{"key":"C","text":"\"Residents in neighborhoods with weekly recycling pickup were 30 percent more likely to also recycle electronic waste than residents without such service.\""},{"key":"D","text":"\"Municipal composting programs in temperate climates processed a higher percentage of yard waste than those in arid regions, where yard waste volumes are naturally lower.\""}]$lyceon_json$::jsonb, 'A', NULL, E'Halperin''s claim is that composting programs underperform because they underestimate the behavioral friction of sustained participation, even among environmentally motivated residents. The quotation showing that only 17 percent of voluntarily enrolled households maintained participation despite strong pro-environmental attitudes directly illustrates the gap between intention and sustained behavior that Halperin describes. The quotation about larger facilities processing more waste addresses infrastructure capacity, not household behavioral barriers. The quotation about recycling pickup and electronic waste concerns a different waste stream entirely and does not address composting participation or behavioral friction. The quotation about climate-related yard waste volume differences pertains to regional waste composition, not to the behavioral challenges Halperin identifies as the core problem.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"C":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2MDT598', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Restoration ecologist Priya Chandran has spent seventeen years studying salt marshes along the Gulf Coast. Her most striking finding is that marshes bordered by mangrove _______ recover from storm damage nearly twice as fast as those without such buffers, a result that has reshaped coastal management policy in several states.', $lyceon_json$[{"key":"A","text":"stands—which act as natural wave barriers—"},{"key":"B","text":"stands, which act as natural wave barriers"},{"key":"C","text":"stands which act as natural wave barriers"},{"key":"D","text":"stands which act as natural wave barriers,"}]$lyceon_json$::jsonb, 'A', NULL, E'The nonrestrictive clause ''which act as natural wave barriers'' must be set off with a matching pair of punctuation marks. The option using paired em dashes correctly encloses the nonrestrictive clause and returns cleanly to the verb ''recover.'' The option with a comma before ''which'' but no closing punctuation after ''barriers'' leaves the nonrestrictive clause unclosed, causing ''recover'' to appear to be part of the subordinate clause rather than the main predicate. The option omitting all punctuation around the clause treats ''which act as natural wave barriers'' as a restrictive modifier, but the clause is parenthetical information—not essential for identifying which mangrove stands—so it must be set off. The option placing a comma only after ''barriers'' but not before ''which'' produces mismatched punctuation that fails to properly delimit the clause.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"sentence_boundary_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2NHEAFI', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 2, 'mcq', E'Which choice completes the text with the most logical transition?', E'During the mid-nineteenth century, the British chemist William Henry Perkin accidentally synthesized mauveine, the first commercially viable aniline dye, while attempting to produce artificial quinine. The discovery transformed the textile industry by making vibrant purple fabric affordable for the first time. _______ Perkin''s work also catalyzed the development of the modern pharmaceutical industry, as researchers began systematically exploring the medicinal properties of coal tar derivatives that had previously been dismissed as industrial waste.', $lyceon_json$[{"key":"A","text":"For instance,"},{"key":"B","text":"On the other hand,"},{"key":"C","text":"Moreover,"},{"key":"D","text":"Instead,"}]$lyceon_json$::jsonb, 'C', NULL, E'The first part of the passage describes one consequence of Perkin''s accidental discovery — the transformation of the textile industry. The sentence after the blank introduces an additional, separate consequence: the catalyzation of the pharmaceutical industry. "Moreover," correctly signals that a further point of similar weight is being added. "For instance," would introduce an example illustrating the textile transformation, but the sentence instead introduces an entirely different industry. "On the other hand," implies a contrasting perspective, yet the pharmaceutical development is presented as a complementary outcome, not an opposing one. "Instead," implies a replacement or substitution, but the pharmaceutical impact did not replace the textile impact — both occurred.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2NMQE03', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 3, 'mcq', E'Which choice completes the text with the most logical transition?', E'Archaeologist Dina Petrov has argued that the Vinča culture of southeastern Europe (c. 5500–4500 BCE) developed a proto-writing system independent of Sumerian cuneiform. Petrov points to the consistent repetition of specific symbols on Vinča pottery fragments across widely separated settlement sites as evidence of a shared communicative convention. Some scholars have countered that mere symbol repetition does not constitute writing, noting that the symbols may have served a purely decorative or ritualistic function with no phonetic or logographic value. _______ Petrov has conceded that no bilingual artifact or statistical pattern yet confirms a linguistic reading of the Vinča symbols, though she maintains that the geographic consistency of the symbol inventory remains unexplained by the decorative hypothesis alone.', $lyceon_json$[{"key":"A","text":"Furthermore,"},{"key":"B","text":"In response,"},{"key":"C","text":"For example,"},{"key":"D","text":"Similarly,"}]$lyceon_json$::jsonb, 'B', NULL, E'The passage presents an academic debate: Petrov advances a claim, opposing scholars challenge it, and the sentence after the blank shows Petrov reacting to that challenge by partially conceding a point while defending her position. "In response," accurately signals that what follows is Petrov''s reply to the counter-argument just described. "Furthermore," would signal an additional supporting point continuing the same line of argument, but the sentence shifts to a concession-plus-defense, which is a dialogic response rather than a simple addition. "For example," would introduce an illustrative instance, but the sentence does not illustrate the critics'' claim — it shifts back to Petrov''s perspective. "Similarly," would draw a parallel between two comparable ideas, but the sentence introduces a concession, not a parallel.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2NOSJCS', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 3, 'mcq', E'Which choice completes the text with the most logical transition?', E'Economist Rui Ferreira has proposed that the rapid adoption of mobile payment platforms in sub-Saharan Africa was driven less by technological innovation per se than by the absence of entrenched banking infrastructure — consumers who lacked access to traditional bank branches had fewer switching costs and thus embraced digital alternatives more readily. In nations with well-established banking networks, by contrast, mobile payment adoption has proceeded more slowly, as consumers and merchants must weigh the convenience of digital transactions against existing relationships with brick-and-mortar institutions. _______ Ferreira''s analysis challenges the common assumption that high mobile-payment adoption rates reflect superior technological ecosystems, suggesting instead that they may indicate gaps in conventional financial services.', $lyceon_json$[{"key":"A","text":"In other words,"},{"key":"B","text":"Consequently,"},{"key":"C","text":"Nonetheless,"},{"key":"D","text":"On the contrary,"}]$lyceon_json$::jsonb, 'A', NULL, E'The preceding sentences lay out Ferreira''s thesis with specific detail — rapid adoption in Africa was driven by the lack of banking infrastructure, while slower adoption elsewhere reflects entrenched banking. The sentence after the blank restates this thesis at a higher level of abstraction: high adoption rates reflect gaps in conventional services rather than superior technology. "In other words," correctly signals a restatement or reformulation of the same idea in different terms. "Consequently," would introduce a new result caused by the preceding information, but the final sentence does not describe a new effect — it summarizes the argument already made. "Nonetheless," implies a concession or contrast with what precedes, yet the final sentence aligns with rather than contradicts the earlier evidence. "On the contrary," signals direct opposition to a preceding claim, but the final sentence supports the same argument rather than opposing it.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2ORTWN8', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 2, 'mcq', E'Which choice best describes the main idea of the text?', E'In 1971, psychologist Philip Zimbardo proposed that anonymity promotes antisocial behavior, a claim that shaped decades of research on crowd dynamics. However, a 2019 meta-analysis by Kira Pronin and colleagues at the University of Lausanne examined 74 studies spanning 48 years and found that the relationship between anonymity and aggression is far weaker than originally reported. Pronin''s team noted that many early studies used small, non-representative samples and that later, larger-scale replications often failed to reproduce the original effect sizes. The meta-analysis concluded that situational context — such as perceived group norms — is a stronger predictor of crowd behavior than anonymity alone.', $lyceon_json$[{"key":"A","text":"A recent comprehensive review challenges the long-held assumption that anonymity is the primary driver of antisocial behavior in crowds."},{"key":"B","text":"Philip Zimbardo's 1971 theory about anonymity has been entirely disproven by modern psychological research."},{"key":"C","text":"Psychologists have determined that group norms are the only factor that influences crowd behavior."},{"key":"D","text":"The University of Lausanne has become the leading institution for research on crowd psychology."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage describes how a 2019 meta-analysis challenged the long-standing claim that anonymity drives antisocial crowd behavior, finding the effect weaker than originally reported and identifying situational context as a stronger predictor. The option stating that a recent comprehensive review challenges the long-held assumption about anonymity captures this central idea accurately. The option claiming Zimbardo''s theory has been entirely disproven overstates the finding — the meta-analysis found the relationship weaker, not nonexistent. The option asserting group norms are the only factor replaces ''stronger predictor'' with an absolute claim the passage does not make. The option about the University of Lausanne''s institutional standing is unsupported; the passage mentions the university only as the researchers'' affiliation.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2OXLQA1', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 3, 'mcq', E'Which choice best describes the main idea of the text?', E'Historian Mariana Caldas argues that the standard periodization of the Brazilian abolitionist movement — which places its origins in the 1860s with organized political societies — obscures the contributions of enslaved people themselves. Caldas points to evidence of coordinated labor refusals on coffee plantations in the Paraíba Valley as early as 1843, actions she characterizes as deliberate political strategy rather than spontaneous resistance. While acknowledging that formal abolitionist organizations amplified the movement''s visibility, Caldas contends that treating their formation as the movement''s starting point implicitly centers elite reformers and marginalizes the agency of the enslaved population whose resistance preceded and arguably catalyzed those organizations.', $lyceon_json$[{"key":"A","text":"Caldas argues that the conventional timeline of Brazilian abolitionism underrepresents the political agency of enslaved people whose organized resistance predated formal abolitionist societies."},{"key":"B","text":"Caldas claims that formal abolitionist organizations in Brazil were entirely irrelevant to the eventual abolition of slavery."},{"key":"C","text":"Caldas demonstrates that labor refusals on coffee plantations were spontaneous acts of desperation rather than calculated political strategies."},{"key":"D","text":"Caldas proposes that the Brazilian abolitionist movement should be dated from the founding of political societies in the 1860s."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage presents Caldas''s argument that standard periodization marginalizes enslaved people''s agency by dating the abolitionist movement from the 1860s, when enslaved people were already engaged in coordinated political resistance decades earlier. The option stating that Caldas argues the conventional timeline underrepresents enslaved people''s political agency accurately captures this nuanced central idea. The option claiming Caldas considers formal organizations entirely irrelevant contradicts the passage, which notes she acknowledges their role in amplifying visibility. The option describing labor refusals as spontaneous acts directly contradicts Caldas''s characterization of them as deliberate political strategy. The option suggesting Caldas proposes dating the movement from the 1860s attributes to her the very position she argues against.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2P9P49L', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 3, 'mcq', E'Which choice most logically completes the text?', E'Literary scholar Fumiko Hayashi argues that the unreliable narrator in Akutagawa Ryūnosuke''s 1922 story "In a Bamboo Grove" functions differently from unreliable narrators in European modernist fiction of the same period. In European works such as Ford Madox Ford''s "The Good Soldier," the reader is positioned to eventually reconstruct a stable truth beneath the narrator''s distortions. Akutagawa, by contrast, presents multiple contradictory testimonies about the same event without privileging any single account. Hayashi notes that no textual evidence within the story allows a reader to definitively rank one testimony as more credible than another. She therefore contends that Akutagawa''s narrative technique ________', $lyceon_json$[{"key":"A","text":"denies the reader the possibility of arriving at a single authoritative version of events, foregrounding the instability of truth itself rather than the psychology of an individual narrator."},{"key":"B","text":"reflects Akutagawa's belief that Japanese literary traditions were aesthetically superior to European modernist conventions."},{"key":"C","text":"was intended primarily as a satire of the Japanese legal system's reliance on witness testimony."},{"key":"D","text":"demonstrates that unreliable narration was a technique invented independently in Japan before European writers adopted it."}]$lyceon_json$::jsonb, 'A', NULL, E'Hayashi''s argument establishes a contrast: European unreliable narrators allow truth reconstruction, while Akutagawa''s multiple contradictory testimonies offer no basis for privileging one account. The option about denying the reader a single authoritative version and foregrounding the instability of truth logically follows from Hayashi''s observation that no testimony can be ranked as more credible. The option about Japanese literary superiority introduces a value judgment the passage never suggests — Hayashi draws a structural distinction, not a qualitative hierarchy. The option about satire of the legal system introduces an authorial intent the passage does not discuss; Hayashi''s analysis is about narrative technique, not social commentary. The option about independent invention and chronological priority introduces a claim about literary history that the passage does not support — Hayashi compares how the technique functions, not who originated it.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2PK4BJP', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 3, 'mcq', E'A student is preparing a presentation slide about the economic impact of coral bleaching on Pacific Island nations. The student wants to acknowledge the severity of the economic losses while also highlighting an adaptive strategy that some communities have pursued. Which choice most effectively uses relevant information from the notes to accomplish this goal?', E'Notes:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2R0PFSC', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 2, 'mcq', E'Which finding from the study, if accurate, would most directly undermine the traditional explanation described in the text?', E'For decades, ornithologists attributed the synchronized dawn chorus of tropical songbirds to territorial signaling — males announcing their presence to rivals before the day''s foraging begins. However, acoustic ecologist Tomás Rennert has proposed an alternative explanation. Rennert suggests that birds sing at dawn primarily because the calm, humid air at that hour transmits sound with minimal distortion, maximizing the effective range of mating calls. Under Rennert''s model, the timing is driven by atmospheric acoustics rather than territorial competition.', $lyceon_json$[{"key":"A","text":"Male songbirds in species with highly overlapping territories do not begin singing earlier or more frequently than males in species with widely spaced territories."},{"key":"B","text":"Dawn chorus vocalizations carry 40 percent farther than identical calls produced at midday in the same habitat."},{"key":"C","text":"Female songbirds show significantly stronger mate-selection responses to dawn calls than to calls produced at other times of day."},{"key":"D","text":"Territorial songbird species that were relocated to arid environments with low dawn humidity continued to produce dawn choruses at the same intensity."}]$lyceon_json$::jsonb, 'A', NULL, E'The traditional explanation holds that dawn singing is driven by territorial competition. If males in species with heavily overlapping territories — where territorial pressure is highest — do not sing earlier or more than males with widely spaced territories, this directly undermines the claim that territorial signaling drives the behavior. The finding about calls carrying farther at dawn supports Rennert''s alternative acoustic model rather than undermining the traditional explanation. The finding about female mate-selection responses supports Rennert''s mating-call hypothesis, not the traditional territorial one. The finding about birds continuing to sing at dawn in arid environments could seem to undermine Rennert''s humidity-based model, but the question asks what undermines the traditional explanation, not Rennert''s alternative.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"C":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2REQ4VV', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 2, 'mcq', E'A student is writing a research summary about termite mound ventilation for a biology class. The student wants to emphasize the contrast between earlier assumptions about termite mound airflow and more recent findings. Which choice most effectively uses relevant information from the notes to accomplish this goal?', E'Notes:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2SJ9GN7', 'RW', 2, 'Craft and Structure', ARRAY['Cross-Text Connections'], 2, 'mcq', E'Which choice best describes the relationship between the two texts?', E'Text 1:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2T2RB0W', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 1, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The Hubbard Brook Experimental Forest in New Hampshire has been the site of continuous ecological research since 1955. Scientists working at the _______ have published over three thousand peer-reviewed studies on nutrient cycling, hydrology, and forest ecology.', $lyceon_json$[{"key":"A","text":"forest,"},{"key":"B","text":"forest"},{"key":"C","text":"forest;"},{"key":"D","text":"forest:"}]$lyceon_json$::jsonb, 'B', NULL, E'The blank falls between a subject (''Scientists working at the forest'') and its verb (''have published''), so no punctuation should separate them. The option without any punctuation after ''forest'' is correct. Placing a comma after ''forest'' incorrectly separates the subject from its predicate. A semicolon after ''forest'' would require two independent clauses, but ''Scientists working at the forest'' is not an independent clause on its own. A colon after ''forest'' would similarly disrupt the subject-verb connection and imply a list or elaboration where none follows.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"D":{"role":"distractor","error_taxonomy":"sentence_boundary_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2TWLJMO', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 1, 'mcq', E'Which finding, if true, would most directly support the researcher''s hypothesis?', E'Marine biologist Elara Voss hypothesizes that deep-sea anglerfish in the Mariana Trench have evolved bioluminescent lures that emit light at wavelengths invisible to their primary predators but visible to their prey. If correct, this adaptation would allow anglerfish to attract food without simultaneously attracting threats. Voss plans to test this hypothesis by measuring the spectral sensitivity of both predator and prey species found in the same depth range.', $lyceon_json$[{"key":"A","text":"Predator species in the Mariana Trench lack photoreceptors sensitive to the wavelengths emitted by anglerfish lures, while prey species possess such photoreceptors."},{"key":"B","text":"Anglerfish in the Mariana Trench are significantly larger than anglerfish species found in shallower ocean zones."},{"key":"C","text":"Prey species in the Mariana Trench are attracted to a wide range of light wavelengths, including those in the visible spectrum."},{"key":"D","text":"Predator species in the Mariana Trench rely primarily on echolocation rather than vision to detect other organisms."}]$lyceon_json$::jsonb, 'A', NULL, E'Voss''s hypothesis is that anglerfish lures emit wavelengths visible to prey but invisible to predators. The finding that predators lack photoreceptors for the lure''s wavelengths while prey possess them would directly confirm the mechanism she proposes. The finding about anglerfish body size is irrelevant to the wavelength-specificity hypothesis. The finding that prey are attracted to a wide range of wavelengths does not address whether predators can see the specific wavelengths the lure emits, leaving half the hypothesis unsupported. The finding about predators using echolocation could explain why predators do not detect anglerfish visually, but it does not address whether the lure''s wavelengths are specifically tuned to prey perception, which is the core of the hypothesis.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2UATV4B', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 3, 'mcq', E'As used in the text, what does the word "arrested" most nearly mean?', E'Paleoclimatologist Renata Okonkwo has proposed that the rapid cooling event at the end of the Eocene epoch arrested the diversification of tropical plant lineages in Southeast Asia. Her fossil pollen analysis reveals that genera which had been proliferating at extraordinary rates abruptly ceased producing new species around 33.7 million years ago, coinciding precisely with the temperature shift.', $lyceon_json$[{"key":"A","text":"halted"},{"key":"B","text":"detained"},{"key":"C","text":"captivated"},{"key":"D","text":"diagnosed"}]$lyceon_json$::jsonb, 'A', NULL, E'The passage describes how a cooling event stopped the process of diversification, making "halted" the correct meaning of "arrested" in this context — it conveys the abrupt cessation of a biological process. "Detained" refers to holding a person in custody, which cannot apply to an abstract biological process. "Captivated" means to charm or fascinate, which is unrelated to the idea of stopping a process. "Diagnosed" means to identify a disease or condition, which does not describe the act of bringing something to a stop.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"vocab_context_error"},"C":{"role":"distractor","error_taxonomy":"vocab_context_error"},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2V64N3E', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 2, 'mcq', E'Which choice best describes the overall structure of the text?', E'Seismologists have long relied on P-waves and S-waves to determine the location of an earthquake''s epicenter. P-waves travel through both solids and liquids and arrive at monitoring stations first, while S-waves move only through solids and arrive second. By measuring the time gap between the two wave types at three or more stations, scientists triangulate the epicenter''s position. However, this traditional method can be unreliable when stations are sparse, as is common in oceanic regions. A newer approach uses hydroacoustic sensors deployed on the ocean floor to detect T-waves — seismic energy converted into sound waves at the ocean-solid earth boundary — enabling detection of submarine earthquakes that the conventional station network might miss entirely.', $lyceon_json$[{"key":"A","text":"It presents an established scientific method, identifies a limitation of that method, and then describes an alternative approach."},{"key":"B","text":"It contrasts two competing theories about earthquake measurement and argues that one is superior."},{"key":"C","text":"It traces the chronological history of seismology from its earliest techniques to its most modern ones."},{"key":"D","text":"It defines a technical process and then provides several examples of its successful application."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage first explains the traditional P-wave/S-wave triangulation method, then notes its limitation in oceanic regions with sparse stations, and finally introduces the hydroacoustic T-wave approach as an alternative — matching the choice that describes presenting an established method, identifying a limitation, and describing an alternative. The choice about contrasting two competing theories is wrong because the passage does not frame the approaches as rival theories or argue one is universally superior. The choice about chronological history is wrong because the passage discusses only two methods rather than tracing a full historical progression of the field. The choice about providing several examples of successful application is wrong because the passage does not offer specific case studies of the method being used successfully.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2V8DPPI', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 1, 'mcq', E'Which choice most logically completes the text?', E'Glacier lilies in the Rocky Mountains typically bloom within days of snowmelt, taking advantage of moist soil and intense sunlight before taller plants leaf out and create shade. Ecologist Priya Dasgupta tracked blooming dates across 13 mountain meadows over a nine-year period and found that in years when spring temperatures were unusually warm, snowmelt occurred three to four weeks earlier than average. In those same years, glacier lilies bloomed correspondingly earlier, but the taller competing plants did not advance their growth schedules by a comparable margin. Dasgupta therefore concluded that unusually warm springs likely ________', $lyceon_json$[{"key":"A","text":"extend the window during which glacier lilies can photosynthesize without competition from taller plants."},{"key":"B","text":"cause glacier lilies to produce fewer seeds due to a shortened growing season."},{"key":"C","text":"reduce the total moisture available in mountain meadow soil."},{"key":"D","text":"allow taller plants to grow at the same accelerated rate as glacier lilies."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage establishes that glacier lilies bloom right after snowmelt and benefit from sunlight before taller plants create shade. In warm springs, lilies bloom much earlier but taller plants do not advance comparably — meaning the gap between lily blooming and tall-plant shading widens. The option about extending the competition-free photosynthesis window follows logically from these facts. The option about fewer seeds introduces a consequence not supported by the passage, which describes an advantage, not a disadvantage. The option about reduced soil moisture introduces a factor the passage does not address. The option about taller plants growing at the same rate directly contradicts the passage''s finding that taller plants did not advance their schedules comparably.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2VT78AF', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 1, 'mcq', E'Which choice completes the text with the most logical transition?', E'Marine biologist Tara Nakamura has spent over a decade studying the symbiotic relationships between cleaner wrasses and larger reef fish in the Coral Sea. Her research has demonstrated that cleaner wrasses remove parasites from the gills and scales of groupers and moray eels, reducing infection rates by as much as 73 percent. _______ Nakamura''s findings suggest that the decline of cleaner wrasse populations could have cascading negative effects on the health of entire reef ecosystems.', $lyceon_json$[{"key":"A","text":"Accordingly,"},{"key":"B","text":"Nevertheless,"},{"key":"C","text":"In contrast,"},{"key":"D","text":"Specifically,"}]$lyceon_json$::jsonb, 'A', NULL, E'The passage establishes that cleaner wrasses significantly reduce infection rates in reef fish, and the sentence after the blank draws a logical consequence from that fact — namely, that losing these wrasses would harm reef ecosystems. "Accordingly," correctly signals a consequence following from the previous evidence. "Nevertheless," implies a contrast or concession, but no contradiction is present. "In contrast," signals an opposing idea, yet the sentence continues the same line of reasoning. "Specifically," would introduce a narrowing detail, but the following sentence broadens the implication rather than narrowing it.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
